        choices: [
          { id: "embodied-knowledge", label: "是的有些知识只能通过做来获得", consequence: { title: "你的倾向：被身体化的认识论", description: "你赞同轮扁：知道如何骑自行车与知道自行车是如何工作的这是两种不同的知识。波兰尼称之为」默会知识「，我们知道的比我们能说出的更多。这种」被身体化的知识「不是」低等「知识，它是最深刻的知识形式。", schools: [{ name: "经验主义", weight: 0.4 }, { name: "存在主义", weight: 0.3 }] }, analysis: "迈克尔·波兰尼在《默会维度》中论证：所有知识，即使是科学知识，都根植于默会的、身体的感知。科学家」有一种感觉「，实验可行，在他们能以命题表达之前。正如轮扁，他们的手比他们的嘴」知道「得更多。", quote: { text: "我们知道的比我们能说出的更多。", attribution: "迈克尔·波兰尼" } },
          { id: "all-knowledge-codifiable", label: "不是所有真正的知识都可以被文字编码", consequence: { title: "你的倾向：命题知识优先论", description: "你认为」不可言传「的东西只是技能或习惯。而不是严格意义上的」知识「。知识是可以用命题表达的可以被记录、传输和验证。轮扁是个伟大的技工。但他不能将技工说成是」知识持有者「。", schools: [{ name: "理性主义", weight: 0.6 }] }, analysis: "这个立场在计算机科学中有一个实际的对应：人工智能能否仅仅从阅读文本中获得所有人类知识，还是需要被身体化的经验？大型语言模型（如GPT）只从文本学习，它们能够获取」实践智慧「吗，还是它们只是」糟粕的读者「？", quote: { text: "如果你不能用语言说出它你就没有真正地理解它。", attribution: "苏格拉底（通过柏拉图）" } }
        ]
