      implications: [{ title: "我们能从文字中学到什么？", body: "轮扁的挑战在现代引发了共鸣：在在线教育和人工智能时代，哪些知识需要身体化的实践和师徒关系？哪些可以纯粹通过」信息传递「获得？轮扁的答案，在技术的喧嚣中，提醒我们去关注那些无法被数字化、被复制、被搜索的」有数存焉「的东西。" }]
