    categories: ["形而上学", "心灵哲学"],
    summary: "一个王子的灵魂带着他的所有记忆进入了一个鞋匠的身体。醒来后。这个」人「觉得自己是王子，他有王子的记忆、信念和性格。他是王子还是鞋匠？洛克说：个人同一性在于记忆。不在于灵魂或物质。",
    coverGradient: "linear-gradient(135deg, #3d2d3d, #5c4f5c)",
